"""Synthetic but realistic logs (generated by readscout, so freely usable): a root cause hidden in noise."""
import random
from pathlib import Path


def _node_log(n, seed):
    rnd = random.Random(seed)
    out, cause_at = [], rnd.randint(n // 3, 2 * n // 3)
    svc = ['api', 'worker', 'scheduler', 'db-pool', 'cache']
    cause = None
    for k in range(n):
        ts = f'2026-10-13T14:{(k // 60) % 60:02d}:{k % 60:02d}.{rnd.randint(0, 999):03d}Z'
        if k == cause_at:
            cause = len(out) + 1
            out += [f'{ts} ERROR db-pool connection to postgres://db:5432/app failed: FATAL: remaining connection slots are reserved for non-replication superuser connections',
                    f'{ts} ERROR worker job sync-{seed} aborted: Error: Pool exhausted after 30000ms',
                    '    at Pool.acquire (node_modules/pg-pool/index.js:210:11)',
                    '    at async syncJob (lib/sync.js:88:19)']
            continue
        r = rnd.random()
        if r < 0.03:
            out.append(f'{ts} WARN cache miss ratio high: {rnd.randint(30, 60)}% (threshold 25%)')
        elif r < 0.05:
            out.append(f'{ts} INFO api GET /api/health 200 0 errors in last window')
        elif r < 0.06:
            out.append(f'{ts} WARN api deprecated header X-Client-Version used by client {rnd.randint(1, 99)}')
        elif r < 0.065:
            out.append(f'{ts} INFO worker retrying job mail-digest after transient timeout (attempt 1/3) - succeeded')
        else:
            out.append(f'{ts} INFO {rnd.choice(svc)} request id={rnd.randint(10**5, 10**6)} handled in {rnd.randint(2, 900)}ms status=200')
    out += ['2026-10-13T15:00:00.000Z ERROR api POST /api/sync 500 Internal Server Error (upstream worker failed)',
            '2026-10-13T15:00:01.000Z INFO scheduler shutting down after 1 failed job']
    return out, cause, 'remaining connection slots'


def _python_log(n, seed):
    rnd = random.Random(seed)
    out, cause_at = [], rnd.randint(n // 3, 2 * n // 3)
    cause = None
    for k in range(n):
        ts = f'2026-10-13 09:{(k // 60) % 60:02d}:{k % 60:02d},{rnd.randint(0, 999):03d}'
        if k == cause_at:
            out += [f'{ts} ERROR [ingest] Failed to process batch 4812',
                    'Traceback (most recent call last):',
                    '  File "/srv/app/ingest/pipeline.py", line 144, in run_batch',
                    '    rows = parse_rows(payload)',
                    '  File "/srv/app/ingest/parse.py", line 57, in parse_rows',
                    "    amount = Decimal(row['amount'])",
                    "decimal.InvalidOperation: [<class 'decimal.ConversionSyntax'>]"]
            cause = len(out)
            continue
        r = rnd.random()
        if r < 0.04:
            out.append(f'{ts} WARNING [http] slow request GET /metrics took {rnd.randint(800, 2000)} ms')
        elif r < 0.06:
            out.append(f'{ts} INFO [ingest] 0 errors, {rnd.randint(100, 900)} rows committed')
        else:
            out.append(f'{ts} INFO [{rnd.choice(["ingest", "http", "auth"])}] ok id={rnd.randint(10**5, 10**6)} in {rnd.randint(1, 300)} ms')
    out += ['2026-10-13 10:00:00,000 ERROR [ingest] batch queue stalled: 1 failed batch, stopping consumer']
    return out, cause, 'InvalidOperation'


def tasks(folder: Path):
    from .generate import Task
    folder.mkdir(parents=True, exist_ok=True)
    out = []
    for name, (lines, cause, key) in {
        'service-800.log': _node_log(800, 1),
        'service-3000.log': _node_log(3000, 2),
        'service-9000.log': _node_log(9000, 3),
        'ingest-4000.log': _python_log(4000, 4),
    }.items():
        p = folder / name
        p.write_text('\n'.join(lines) + '\n', encoding='utf-8')
        out.append(Task(f'logs:{name}', 'log', 'easy' if '800' in name else 'medium', folder, [name],
                        'What went wrong? Give first the earliest root-cause error, then the consequences. Ignore noise.',
                        [{'line': cause, 'key': key, 'path': name, 'span': [cause - 6, cause + 3]}]))
    return out
